def solve():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    a = list(map(int, data[1:n+1]))

    b = [0] * n

    for i in range(n):
        if i % 2 == 0:
            b[i] = a[n - 1 - (i // 2) * 2]
        else:
            b[i] = a[n - (i // 2) * 2 - 1]

    print(" ".join(map(str, b)))
